from difflib import get_close_matches as closest_matches

from thefuck.utils import (get_all_executables, get_closest,
                           get_valid_history_without_current)
from thefuck.specific.sudo import sudo_support


@sudo_support
def match(command):
    if not command.script_parts:
        return False
    if 'not found' not in command.stderr:
        return False
    suggestions = closest_matches(command.script_parts[0],
                                  get_all_executables())
    return len(suggestions) > 0


def _history_executables(command):
    history = get_valid_history_without_current(command)
    for entry in history:
        parts = entry.split(' ')
        yield parts[0]


@sudo_support
def get_new_command(command):
    mistyped = command.script_parts[0]

    # First, try something from history:
    from_history = get_closest(mistyped, _history_executables(command),
                               fallback_to_first=False)
    candidates = [from_history] if from_history else []

    # Then, add matches from all executables:
    for candidate in closest_matches(mistyped, get_all_executables()):
        if candidate not in candidates:
            candidates.append(candidate)

    results = []
    for candidate in candidates:
        remainder = command.script_parts[1:]
        results.append(' '.join([candidate] + remainder))
    return results


